(()=>{const $=id=>document.getElementById(id);let jobs=[],current;const api=async body=>{const r=await fetch('/api/studio/jobs',body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{}),d=await r.json();if(!r.ok)throw Error(d.error);return d;};async function load(id){try{jobs=(await api()).jobs;$('job-select').replaceChildren();for(const j of jobs){const o=document.createElement('option');o.value=j.id;o.textContent=j.title+' · '+j.stage;$('job-select').append(o);}if(id)$('job-select').value=id;render();}catch(e){$('job-status').textContent=e.message;}}function render(){current=jobs.find(j=>j.id===$('job-select').value);$('job-actions').replaceChildren();$('job-brief').textContent=current?current.brief+' · '+current.mediaIds.length+' saved assets'+(current.learning?' · Next action: '+current.learning:''):'Create a job or run your business workflow to begin.';if(!current)return;const next={Brief:['Creating'],Creating:['Review'],Review:['Creating','Approved'],Approved:['Review','Publish handoff'],'Publish handoff':['Review']};for(const stage of next[current.stage]||[]){const b=document.createElement('button');b.textContent=stage==='Publish handoff'?'Prepare publishing handoff':'Move to '+stage;b.onclick=()=>change({action:'stage',stage});$('job-actions').append(b);}const attach=document.createElement('button');attach.textContent='Attach an existing file';attach.onclick=async()=>{try{const r=await fetch('/api/designer/media'),d=await r.json();if(!r.ok)throw Error(d.error);const dialog=document.createElement('dialog'),close=document.createElement('button');close.textContent='Close';close.onclick=()=>dialog.remove();dialog.append(close);for(const f of d.files){const b=document.createElement('button');b.textContent=f.name;b.onclick=async()=>{await window.attachStudioMedia(f.id);dialog.remove();};dialog.append(b);}document.body.append(dialog);dialog.showModal();}catch(e){$('job-status').textContent=e.message;}};$('job-actions').append(attach);if(current.stage==='Publish handoff'){const b=document.createElement('button');b.textContent='Record actual campaign results';b.onclick=()=>{const source=prompt('Public post URL (after you publish manually)');if(!source)return;const values={};for(const k of ['views','enquiries','sales']){const v=prompt('Actual '+k+' count');if(v===null||v.trim()==='')return;values[k]=Number(v);}change({action:'measure',source,...values});};$('job-actions').append(b);$('job-status').textContent='Publishing authorization required. This handoff does not post automatically.';}}
async function change(body){if(!current)return;const id=current.id;try{await api({...body,id,revision:current.revision});$('job-status').textContent='Saved to Bonga Bhengu OS.';await load(id);}catch(e){$('job-status').textContent=e.message;await load(id);}}window.attachStudioMedia=async mediaId=>{if(!current)throw Error('Recording saved, but choose a creative job to attach it.');const id=current.id;await api({action:'attach',id,revision:current.revision,mediaId});await load(id);};$('job-select').onchange=render;$('job-route').onclick=async()=>{try{await api({action:'route'});await load();}catch(e){$('job-status').textContent=e.message;}};$('job-new').onclick=async()=>{const title=prompt('What are you creating?');if(!title)return;const brief=prompt('Audience, message and deliverable')||'';try{const j=await api({action:'create',title,brief});await load(j.id);}catch(e){$('job-status').textContent=e.message;}};load();})();